import{_ as e,o as s,c as n,j as a}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"什么是上下文切换","description":"","frontmatter":{"title":"什么是上下文切换","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","核心API","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第三部分：核心 API/07-异常与线程/线程和进程区别/什么是上下文切换.md","filePath":"posts/java快速入门/第三部分：核心 API/07-异常与线程/线程和进程区别/什么是上下文切换.md"}'),o={name:"posts/java快速入门/第三部分：核心 API/07-异常与线程/线程和进程区别/什么是上下文切换.md"};function l(r,t,p,_,d,i){return s(),n("div",null,[...t[0]||(t[0]=[a("div",null,[a("p",null,"多线程编程中一般线程的个数都大于 CPU 核心的个数，而一个 CPU 核心在任意时刻只能被一个线程使用，为了让这些线程都能得到有效执行，CPU 采取的策略是为每个线程分配时间片并轮转的形式。当一个线程的时间片用完的时候就会重新处于就绪状态让给其他线程使用，这个过程就属于一次上下文切换。"),a("p",null,"概括来说就是：当前任务在执行完 CPU 时间片切换到另一个任务之前会先保存自己的状态，以便下次再切换回这个任务时，可以再加载这个任务的状态。任务从保存到再加载的过程就是一次上下文切换。"),a("p",null,"上下文切换通常是计算密集型的。也就是说，它需要相当可观的处理器时间，在每秒几十上百次的切换中，每次切换都需要纳秒量级的时间。所以，上下文切换对系统来说意味着消耗大量的 CPU 时间，事实上，可能是操作系统中时间消耗最大的操作。"),a("p",null,"Linux 相比与其他操作系统（包括其他类 Unix 系统）有很多的优点，其中有一项就是，其上下文切换和模式切换的时间消耗非常少。")],-1)])])}const P=e(o,[["render",l]]);export{u as __pageData,P as default};
